/// <summary>
/// Form class for selecting the origin document line for a weight in history record.
/// </summary>
[Form]
public class AVARUMWeightInOriginSelection extends FormRun
{
    AVARUMWeightInHistory weightInHistory;

}

/// <summary>
/// Initializes the form, sets up data sources and controls based on the origin of the weight in history record.
/// </summary>
public void init()
{
    FormBuildDesign fd;
    FormControlName fcName;  
    FormBuildGroupControl contentGrpCtrl; 
    FormBuildGroupControl contentFilterGrpCtrl;
    QuickFilterControlBuild quickFilterCtrl;
    FormBuildGridControl gridCtrl;
    FormBuildStringControl idStrCtrl;
    FormBuildStringControl accountStrCtrl;
    FormBuildStringControl accountNameStrCtrl;
    FormBuildStringControl itemIdStrCtrl;
    FormBuildStringControl itemNameStrCtrl;
    FormBuildRealControl qtyOrderedRealCtrl;

    weightInHistory = this.args().record();   

    if (!weightInHistory || weightInHistory.TableId != tableNum(AVARUMWeightInHistory))
    {
        throw Global::error("@AVARUM:NoRecordSelected");
    }

    fd = this.form().design();

    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentContent);
    contentGrpCtrl = fd.control(fcName);
    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentLineFilterGroup);
    contentFilterGrpCtrl = fd.control(fcName);            
    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentLineQuickFilter);
    quickFilterCtrl = fd.control(fcName);
    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentLineGrid);
    gridCtrl = fd.control(fcName);
    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentLine_Id);
    idStrCtrl = fd.control(fcName);
    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentLine_AccountNum);
    accountStrCtrl = fd.control(fcName);
    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentLine_AccountName);
    accountNameStrCtrl = fd.control(fcName);
    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentLine_ItemId);
    itemIdStrCtrl = fd.control(fcName);
    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentLine_ItemName);
    itemNameStrCtrl = fd.control(fcName);
    fcName = formControlStr(AVARUMWeightInOriginSelection, DocumentLine_QtyOrdered);
    qtyOrderedRealCtrl = fd.control(fcName);

    switch (weightInHistory.OriginId)
    {
        case AVARUMWeightInOrigin::Purch:
            fd.caption("@SYS336224");

            contentGrpCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, PurchLine));
            contentFilterGrpCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, PurchLine));
            gridCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, PurchLine));
            idStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, PurchLine));
            idStrCtrl.dataField(fieldNum(PurchLine, PurchId));
            quickFilterCtrl.defaultColumnName(fieldStr(PurchLine, PurchId));
            accountStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, PurchLine));
            accountStrCtrl.dataField(fieldNum(PurchLine, VendAccount));
            accountNameStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, PurchLine));
            accountNameStrCtrl.dataMethod(tableMethodStr(PurchLine, vendName_AVA));
            itemIdStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, PurchLine));
            itemIdStrCtrl.dataField(fieldNum(PurchLine, ItemId));
            itemNameStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, PurchLine));
            itemNameStrCtrl.dataMethod(tableMethodStr(PurchLine, ItemName));
            qtyOrderedRealCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, PurchLine));
            qtyOrderedRealCtrl.dataField(fieldNum(PurchLine, QtyOrdered));
            break;

        case AVARUMWeightInOrigin::Sales:
            fd.caption("@SYS336324");

            contentGrpCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, SalesLine));
            contentFilterGrpCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, SalesLine)); 
            gridCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, SalesLine));
            idStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, SalesLine));
            idStrCtrl.dataField(fieldNum(SalesLine, SalesId));
            quickFilterCtrl.defaultColumnName(fieldStr(SalesLine, SalesId));
            accountStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, SalesLine));
            accountStrCtrl.dataField(fieldNum(SalesLine, CustAccount));
            accountNameStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, SalesLine));
            accountNameStrCtrl.dataMethod(tableMethodStr(SalesLine, custName_AVA));
            itemIdStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, SalesLine));
            itemIdStrCtrl.dataField(fieldNum(SalesLine, ItemId));
            itemNameStrCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, SalesLine));
            itemNameStrCtrl.dataMethod(tableMethodStr(SalesLine, ItemName));
            qtyOrderedRealCtrl.dataSource(formDataSourceStr(AVARUMWeightInOriginSelection, SalesLine));
            qtyOrderedRealCtrl.dataField(fieldNum(SalesLine, QtyOrdered));
            break;
    }

    super();

    if (!weightInHistory)
    {
        throw Global::error("@AVARUM:NoRecordSelected");
    }

    switch (weightInHistory.OriginId)
    {
        case AVARUMWeightInOrigin::Purch:             
            PurchLine_ds.executeQuery();
            break;

        case AVARUMWeightInOrigin::Sales:
            SalesLine_ds.executeQuery();
            break;

        default:                                                                            
            throw Global::error(strFmt("@AVARUM:WeightInUnsupportedOriginId", AVARUMWeightInManager::WeightInOriginDE.value2Label(weightInHistory.OriginId)));
    }
}

/// <summary>
/// Event handler for the OK button. Moves the weight in history to the selected document line.
/// </summary>
public void closeOk()
{
    Common documentLine;
    DataSourceName dsUpdateName;

    switch (weightInHistory.OriginId)
    {
        case AVARUMWeightInOrigin::Purch:
            documentLine = PurchLine_ds.cursor();
            dsUpdateName = formDataSourceStr(AVARUMWeightIn, PurchLine);
            break;

        case AVARUMWeightInOrigin::Sales:
            documentLine = SalesLine_ds.cursor();
            dsUpdateName = formDataSourceStr(AVARUMWeightIn, SalesLine);
            break;
    }

    if (!documentLine)
    {
        throw Global::error("@AVARUM:NoLineSelected");
    }

    super();

    try
    {     
        AVARUMWeightInManager::moveWeightInHistory(weightInHistory, documentLine.RecId);

        if (FormDataUtil::isFormDataSource(weightInHistory))
        {
            FormDataSource formDataSource;

            formDataSource = FormDataUtil::getFormDataSource(weightInHistory);

            /// Re-execute the query to reflect the changes made.
            formDataSource.executeQuery();

            // A call to active() is needed to trigger the design update logic.
            formDataSource.active();

            if (this.args().caller() is IFormDataSourceManager)
            {
                IFormDataSourceManager fdsManager = this.args().caller();
                fdsManager.setRecord(dsUpdateName, documentLine);
            }
        }
    }
    catch
    {
        /// Exceptios handled in the manager class, just fall through here.
        Global::exceptionTextFallThrough();
    }          
}

/// <summary>
/// Initializes the SalesLine data source
/// </summary>
public void init()
{
    QueryBuildDataSource qbdsSalesLine;
    QueryBuildDataSource queryBuildDataSourceInventTable;
    QueryBuildDataSource qbdsWeightInHistory;

    super();

    qbdsSalesLine = this.query().dataSourceTable(tableNum(SalesLine));
    qbdsSalesLine.addRange(fieldNum(SalesLine, RemainSalesPhysical)).value(Global::queryValue('>0'));
    qbdsSalesLine.addRange(fieldNum(SalesLine, SalesType)).value(Global::queryValue(SalesType::Sales));
    qbdsSalesLine.addRange(fieldNum(SalesLine, RecId)).value(SysQuery::valueNot(Global::queryValue(weightInHistory.OriginRefRecId)));

    queryBuildDataSourceInventTable = qbdsSalesLine.addDataSource(tablenum(InventTable));
    queryBuildDataSourceInventTable.addRange(fieldNum(InventTable, AVARUMWeighSales)).value(Global::queryValue(NoYes::Yes));
    queryBuildDataSourceInventTable.relations(true);
    queryBuildDataSourceInventTable.joinMode(JoinMode::ExistsJoin);

    qbdsWeightInHistory = qbdsSalesLine.addDataSource(tableNum(AVARUMWeightInHistory));
    qbdsWeightInHistory.relations(false);
    qbdsWeightInHistory.addLink(fieldNum(SalesLine, RecId), fieldNum(AVARUMWeightInHistory, OriginRefRecId));
    qbdsWeightInHistory.addRange(fieldNum(AVARUMWeightInHistory, OriginId)).value(Global::queryValue(AVARUMWeightInOrigin::Sales));
    qbdsWeightInHistory.addRange(fieldNum(AVARUMWeightInHistory, OriginRefTableId)).value(Global::queryValue(tableNum(SalesLine)));
    qbdsWeightInHistory.joinMode(JoinMode::NoExistsJoin);
}

/// <summary>
/// Initializes the PurchLine data source, adds ranges and joins to InventTable.
/// </summary>
public void init()
{
    QueryBuildDataSource qbdsPurchLine;
    QueryBuildDataSource queryBuildDataSourceInventTable;
    QueryBuildDataSource qbdsWeightInHistory;

    super();

    qbdsPurchLine = this.query().dataSourceTable(tableNum(PurchLine));
    qbdsPurchLine.addRange(fieldNum(PurchLine, RemainPurchPhysical)).value(Global::queryValue('>0'));
    qbdsPurchLine.addRange(fieldNum(PurchLine, PurchaseType)).value(Global::queryValue(PurchaseType::Purch));
    qbdsPurchLine.addRange(fieldNum(PurchLine, RecId)).value(SysQuery::valueNot(Global::queryValue(weightInHistory.OriginRefRecId)));

    queryBuildDataSourceInventTable = qbdsPurchLine.addDataSource(tablenum(InventTable));
    queryBuildDataSourceInventTable.addRange(fieldNum(InventTable, AVARUMWeighBlanket)).value(Global::queryValue(NoYes::Yes));
    queryBuildDataSourceInventTable.relations(true);
    queryBuildDataSourceInventTable.joinMode(JoinMode::ExistsJoin);

    qbdsWeightInHistory = qbdsPurchLine.addDataSource(tableNum(AVARUMWeightInHistory));
    qbdsWeightInHistory.relations(false);
    qbdsWeightInHistory.addLink(fieldNum(PurchLine, RecId), fieldNum(AVARUMWeightInHistory, OriginRefRecId));
    qbdsWeightInHistory.addRange(fieldNum(AVARUMWeightInHistory, OriginId)).value(Global::queryValue(AVARUMWeightInOrigin::Purch));
    qbdsWeightInHistory.addRange(fieldNum(AVARUMWeightInHistory, OriginRefTableId)).value(Global::queryValue(tableNum(PurchLine)));
    qbdsWeightInHistory.joinMode(JoinMode::NoExistsJoin);
}
